"""Generate the dossier from the exact publication banks, without claiming human approval."""
import pathlib,json
ROOT=pathlib.Path(__file__).resolve().parents[1];r=ROOT/'web/coleccion-juridica';c=json.loads((r/'catalog.json').read_text());out=ROOT/'docs/coleccion';date=c['verifiedDate']
lines=['# Dossier jurídico — colección de iNavarro Abogados','',f'Verificación documental de Codex: **{date}**. Se revisaron los 60 enunciados, 180 alternativas, respuestas, explicaciones, matices y referencias. Este documento se genera de los mismos bancos que se compilan. No consta ni se atribuye aprobación profesional humana ni revisión de vLex Vincent. La instrucción del titular autoriza la publicación; no se interpreta como validación jurídica personal de cada caso.','', '## Correcciones cerradas documentalmente','', '- Sucesiones 03: se mencionan ambos hijos y se les atribuyen 100 € a cada uno, con caudal neto concreto. Se plantea complemento de legítima, no una preterición no intencional; arts. 814 y 815 CC diferenciados.','- Sucesiones 08: Eva debe aceptar la herencia de Luis para ejercer el derecho transmitido, sin quedar obligada a aceptar la de la primera causante. STS 539/2013, 11-9-2013, ECLI:ES:TS:2013:5269, identificada en la Biblioteca Jurídica del BOE; doctrina contrastada en el comentario oficial publicado y contrastada en fuente TEAC. El enlace de CENDOJ ofrecido por BOE devolvió 403, por lo que no se afirma lectura directa allí.','- Sucesiones 09: no se sustituye por mayoría el consentimiento discrepante. Se separan prueba y eficacia del pacto, posible cumplimiento, contador-partidor dativo con requisitos y división judicial.','- Vivienda 01 y 07: hechos posteriores a la entrada en vigor de la reforma consultada. El caso 07 fija firma el 10-10-2026 y decisión el 3-11-2026: aún no han transcurrido seis meses; se diferencia vivienda habitual de temporal. No se traslada sin comprobar una indemnización de una versión anterior de la ley.','- Consumo 07: seis meses desde entrega como caducidad para el saneamiento por vicios ocultos, no prescripción. Art. 7 LO 1/2025: suspensión con solicitud de negociación que cumpla los requisitos; no reinicio de seis meses completos.','- Consumo 10: daños materiales conocidos en un supuesto ordinario del art. 1902 CC, un año y MASC acreditado. Interrupción/reinicio de la prescripción frente a suspensión/reanudación de caducidad. El requisito de procedibilidad no amplía universalmente el plazo material.','- Penal 10: máximo de multa de **al menos seis meses**, incluido el máximo de seis meses del supuesto. No se cambia por «más de seis».','- Extranjería 05: cónyuge peruana adulta de español, nueva solicitud de 2026, sin libre circulación ejercida ni título previo. Se delimita el capítulo VII del RD 1155/2024.','- Extranjería 08: renovación ordinaria por cuenta ajena, tres meses transcurridos sin suspensión ni ampliación: silencio positivo (art. 80.9). Extranjería 10: renovación en los dos meses previos, continuidad laboral y requisitos cumplidos: prórroga de validez hasta resolución (art. 80.1).','- Los demás casos se comprobaron en sus fuentes y se reescribieron sus alternativas. Las posiciones correctas se distribuyen de forma diferente por especialidad; se combinan respuestas correctas cortas, medias y largas sin asociar el acierto a una longitud fija.','', '## Vigencia y revisiones futuras','', '- RDL 29/2026: publicación oficial BOE de 7-10-2026; entrada en vigor observada el 8-10-2026. Se contrastaron publicación y texto consolidado. A fecha de comprobación no se ha identificado en la ficha oficial una resolución de convalidación: **no se afirma convalidación**. Debe comprobarse cualquier resolución posterior de convalidación o derogación, además de las normas transitorias, antes de modificar los supuestos. El precedente RDL 26/2026 no se trata como norma vigente.','- LAU: controlar reformas, reglas temporales e índices. No se declara Tenerife zona tensionada ni se calcula una actualización. Los supuestos de desistimiento están fechados; no deben desplazarse de fecha conservando automáticamente la misma solución.','- MASC: contrastar art. 7 LO 1/2025 y normativa especial antes de calcular plazos en un caso real. Se distinguió entrada en vigor del título II el 3-4-2025 y régimen transitorio de procedimientos; no se proyecta automáticamente sobre procedimientos previos.','- Extranjería: revisar modificaciones del RD 1155/2024 y delimitación de regímenes, así como efectos de nuevas resoluciones y normativa de la Unión. No se incluyen vías de regularización no verificadas ni se promete autorización o expulsión.','- Sucesiones y familia aplican Derecho civil común. Elementos internacionales, otro derecho civil aplicable o circunstancias no incluidas pueden exigir una solución distinta.','', '## Evidencia y fuentes oficiales','', '`fuentes-verificadas.json` conserva fecha, URL, estado HTTP y hash de cada norma descargada. `articulos-comprobados.json` localiza referencias, pero la existencia de un artículo no sustituye su lectura e interpretación. `NOTAS-NORMATIVAS.md` registra las fuentes adicionales y limitaciones de acceso.','']
summary=['# Fuentes jurídicas de la colección','', f'Verificación documental de Codex: {date}. No se atribuye aprobación profesional humana. Dossier íntegro: `DOSSIER-JURIDICO.md`.','']
for s in c['sources'].values():
 line=f"- [{s['name']}]({s['url']})";lines.append(line);summary.append(line)
for meta in c['games']:
 g=json.loads((r/'data'/f"{meta['slug']}.json").read_text());lines+=['',f"## {g['title']} — {g['area']}",'',g['intro']];summary+=['',f"## {g['title']}",'','| Caso | Fundamento |','| --- | --- |']
 for i,q in enumerate(g['questions']):
  refs='; '.join(c['sources'][ref['source']]['name']+', '+('art. ' if not ref['articles'].startswith('disposición') else '')+ref['articles'] for ref in q['references'])
  summary.append(f"| {i+1}. {q['title']} | {refs} |")
  lines+=['',f"### {i+1}. {q['title']}",'',f"Ámbito: {q['territory']}. Comprobación documental: {q['verifiedDate']}. Dificultad: {q['difficulty']}/3.",'',q['situation'],'']
  for n,o in enumerate(q['options']):lines.append(f"- {chr(65+n)}. {o}"+(' **[Respuesta correcta para este supuesto]**' if n==q['correct'] else ''))
  lines+=['','Explicación: '+q['explanation'],'','Matiz: '+q['nuance'],'','Fundamento: '+refs+'.']
  for j in q.get('jurisprudence',[]):lines+=['',f"Jurisprudencia: [{j['name']}]({j['url']}). {j['note']}"]
  lines+=['','Consulta relacionada: '+q['consult']+'.']
(out/'DOSSIER-JURIDICO.md').write_text('\n'.join(lines)+'\n');(out/'FUENTES.md').write_text('\n'.join(summary)+'\n');print('Dossier sincronizado: 60 casos completos y fuentes de publicación.')
